                                                           // compare module set
#define SYSCTL_REGPARITY_ERR_FLG_SET_KEY_S   24U
#define SYSCTL_REGPARITY_ERR_FLG_SET_KEY_M   0xFF000000U   // KEY field

//*************************************************************************************************
//
